"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[3377],{2685(s){s.exports=JSON.parse('{"tag":{"label":"one-way-functions","permalink":"/azeon/p-vs-np/tags/one-way-functions","allTagsPath":"/azeon/p-vs-np/tags","count":2,"items":[{"id":"failed-proofs/cryptography-vs-natural-proofs","title":"Cryptography vs. Natural Proofs","description":"Secure encryption needs functions that look random but aren\'t. If such functions exist, they hide their own simplicity so well that the natural way of proving hardness can\'t see it. The thing we want to prove protects itself.","permalink":"/azeon/p-vs-np/failed-proofs/cryptography-vs-natural-proofs"},{"id":"real-world-impact/hash-functions-and-passwords","title":"Hash Functions & Passwords","description":"A good website never knows your password. It stores a fingerprint that\'s easy to compute and believed to be infeasible to reverse. Here\'s how that works, and why the protection isn\'t NP-Hardness, even though it does depend on P \u2260 NP.","permalink":"/azeon/p-vs-np/real-world-impact/hash-functions-and-passwords"}],"unlisted":false}}')}}]);